import {
  type ConversationActionDialogName,
  ConversationActionDialogs,
  ConversationActions,
} from '@github-ui/copilot-chat/components/conversation/ConversationActions'
import {useActivePlugin} from '@github-ui/copilot-chat/hooks/use-active-plugin'
import {useSelectedCopilotSpaceId} from '@github-ui/copilot-chat/hooks/use-selected-custom-copilot-id'
import {
  COPILOT_PATH,
  COPILOT_SPACES_PATH,
  findAgentCorrespondents,
  threadName as getThreadName,
} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
// eslint-disable-next-line no-restricted-imports
import {useChatState, useChatStateLens} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import {getCopilotSpacePath, useIsCopilotSpacesPage} from '@github-ui/copilot-chat/utils/custom-copilots-helpers'
import {getSelectedThread} from '@github-ui/copilot-chat/utils/get-selected-thread'
import {useCustomCopilotsEnabled, useFetchCopilotSpace} from '@github-ui/copilot-spaces/hooks'
import {setTitle} from '@github-ui/document-metadata'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useNavigableRef} from '@github-ui/navigable-ref'
import {Breadcrumbs} from '@github-ui/pacer/Breadcrumbs'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {LockIcon, SidebarExpandIcon, UnlockIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, IconButton} from '@primer/react'
import {useEffect, useMemo, useRef, useState} from 'react'
import {flushSync} from 'react-dom'

import {useBooleanState} from '../hooks/use-boolean-state'
import {useIsSharedThread} from '../hooks/use-is-shared-thread'
import {useRouteThreadId} from '../hooks/use-route-thread-id'
import type {CopilotImmersivePayload} from '../routes/payloads'
import {useContentPreview, useContentPreviewOpen} from './ContentPreview/ContentPreviewContext'
import styles from './Header.module.css'
import {NewChatButton} from './NewChatButton'
import {useGlobalNavigation} from './Spaces/hooks/use-global-navigation'
import {StaffToolsMenu} from './StaffToolsMenu'

export interface HeaderProps {
  showPreviewPaneButton?: boolean
  conversationSpecificItems?: React.ReactNode
  customButtons?: React.ReactNode
  defaultName?: string
  returnFocusRef?: React.RefObject<HTMLButtonElement | null>
  onBreadcrumbMenuRefReady?: (ref: React.RefObject<HTMLButtonElement | null>) => void
}

export function Header({
  showPreviewPaneButton = true,
  conversationSpecificItems,
  customButtons,
  defaultName = '',
  returnFocusRef,
  onBreadcrumbMenuRefReady,
}: HeaderProps) {
  const state = useChatState()
  const {selectedThreadID, threads, messagesLoading, messages} = state
  const thread = useChatStateLens(s => getSelectedThread(s))
  const threadName = getThreadName(thread)
  const isSharedThread = useIsSharedThread()
  const routeThreadId = useRouteThreadId()
  const selectedCopilotSpaceId = useSelectedCopilotSpaceId()
  const {data: selectedCopilotSpace} = useFetchCopilotSpace(selectedCopilotSpaceId)
  const isCustomCopilotsEnabled = useCustomCopilotsEnabled()
  const isSpacesPage = useIsCopilotSpacesPage()
  const activePlugin = useActivePlugin()
  const [, startLoading, stopLoading] = useBooleanState(false)

  const selectedThread = threads.get(selectedThreadID!)
  const hasSharedId = Boolean(isSharedThread ? routeThreadId : selectedThread?.sharedID)

  const {updateGlobalNavigationBreadcrumbs} = useGlobalNavigation()

  useEffect(() => {
    updateGlobalNavigationBreadcrumbs()
  }, [updateGlobalNavigationBreadcrumbs, selectedCopilotSpaceId])

  const getThreadUrl = () => {
    if (!selectedThreadID) {
      return COPILOT_PATH
    }

    if (isSharedThread && routeThreadId) {
      return `/copilot/share/${routeThreadId}`
    }

    return `/copilot/c/${selectedThreadID}`
  }

  // Don't show breadcrumb if we are on the top level
  const isTopLevel = useMemo(() => {
    return (isSpacesPage && !selectedCopilotSpaceId) || (!selectedThreadID && !activePlugin?.id && !isSpacesPage)
  }, [isSpacesPage, selectedCopilotSpaceId, selectedThreadID, activePlugin?.id])

  const spaceMenuButtonRef = useRef<HTMLButtonElement>(null)
  const threadMenuButtonRef = useRef<HTMLButtonElement>(null)
  const shareButtonRef = useRef<HTMLButtonElement>(null)
  const [dialogOpenerRef, setDialogOpenerRef] = useState<React.RefObject<HTMLElement | null> | null>(null)

  // Use the provided returnFocusRef, or fall back to the appropriate menu button
  // The thread menu takes precedence since it's the deepest/rightmost breadcrumb
  const anchorRef = returnFocusRef || (selectedThreadID ? threadMenuButtonRef : spaceMenuButtonRef)

  // Expose the breadcrumb menu ref to parent components so they can manage focus for their own dialogs
  useEffect(() => {
    if (onBreadcrumbMenuRefReady) {
      onBreadcrumbMenuRefReady(selectedThreadID ? threadMenuButtonRef : spaceMenuButtonRef)
    }
  }, [onBreadcrumbMenuRefReady, selectedThreadID, threadMenuButtonRef, spaceMenuButtonRef])

  const [conversationDialog, setConversationDialog] = useState<ConversationActionDialogName | null>(null)

  const {canShareThread} = useAppPayload<CopilotImmersivePayload>()
  const messagesLoaded = messagesLoading.state === 'loaded'

  const showShareButton =
    canShareThread && !isSharedThread && selectedThreadID && !selectedCopilotSpaceId && messagesLoaded

  // Share button logic (merged from share-conversation-btn.tsx)
  const hasExtensions = findAgentCorrespondents(messages).length > 0
  const isInactive = hasExtensions

  const openShareDialog = () => {
    if (isInactive) return
    setDialogOpenerRef(shareButtonRef)
    setConversationDialog('share')
  }

  if (selectedCopilotSpace) {
    if (thread) {
      setTitle(`${threadName} · ${selectedCopilotSpace.name} · GitHub Copilot Spaces`)
    } else {
      setTitle(`${selectedCopilotSpace.name} · GitHub Copilot Spaces`)
    }
  } else if (selectedCopilotSpaceId) {
    // While loading the space, show a generic title
    if (thread) {
      setTitle(`${threadName} · GitHub Copilot Spaces`)
    } else {
      setTitle('GitHub Copilot Spaces')
    }
  } else if (isSpacesPage) {
    setTitle('Spaces · GitHub Copilot')
  } else if (isSharedThread) {
    setTitle(`Shared conversation · GitHub Copilot`)
  } else {
    setTitle(`${threadName} · GitHub Copilot`)
  }

  return (
    <div className={styles.container}>
      <div className={styles.leftControls}>
        <NewChatButton />
        {!isTopLevel && !isSharedThread && (
          <Breadcrumbs>
            {isCustomCopilotsEnabled && (selectedCopilotSpace || defaultName) ? (
              // Spaces with selected space
              <>
                <Breadcrumbs.Item href={COPILOT_SPACES_PATH}>Spaces</Breadcrumbs.Item>
                {selectedThreadID || !conversationSpecificItems ? (
                  <Breadcrumbs.Item
                    href={selectedCopilotSpace ? getCopilotSpacePath(selectedCopilotSpace) : COPILOT_SPACES_PATH}
                  >
                    {selectedCopilotSpace?.name || defaultName}
                  </Breadcrumbs.Item>
                ) : (
                  <Breadcrumbs.ItemWithMenu
                    buttonRef={spaceMenuButtonRef}
                    menuOverlay={
                      <ActionMenu.Overlay>
                        <ActionList>{conversationSpecificItems}</ActionList>
                      </ActionMenu.Overlay>
                    }
                  >
                    {selectedCopilotSpace?.name || defaultName}
                  </Breadcrumbs.ItemWithMenu>
                )}
                {selectedThreadID && (
                  <Breadcrumbs.ItemWithMenu
                    buttonRef={threadMenuButtonRef}
                    menuOverlay={
                      <ActionMenu.Overlay>
                        <ActionList>
                          <ConversationActions
                            onOpenDialog={dialog => {
                              setDialogOpenerRef(threadMenuButtonRef)
                              setConversationDialog(dialog)
                            }}
                            isShared={hasSharedId}
                            showShare={!selectedCopilotSpaceId}
                            hideShareOnDesktop
                            threadName={threadName}
                            threadId={selectedThreadID}
                          />
                        </ActionList>
                      </ActionMenu.Overlay>
                    }
                  >
                    {threadName}
                  </Breadcrumbs.ItemWithMenu>
                )}
              </>
            ) : activePlugin ? (
              // Plugin page
              <Breadcrumbs.Item href={`/copilot/${activePlugin.id}`}>
                {activePlugin.displayName || 'Plugin'}
              </Breadcrumbs.Item>
            ) : selectedThreadID && !isSharedThread ? (
              <Breadcrumbs.ItemWithMenu
                buttonRef={threadMenuButtonRef}
                menuOverlay={
                  <ActionMenu.Overlay>
                    <ActionList>
                      <ConversationActions
                        onOpenDialog={dialog => {
                          setDialogOpenerRef(threadMenuButtonRef)
                          setConversationDialog(dialog)
                        }}
                        isShared={hasSharedId}
                        showShare={!selectedCopilotSpaceId}
                        hideShareOnDesktop
                        threadName={threadName}
                        threadId={selectedThreadID}
                      />
                    </ActionList>
                  </ActionMenu.Overlay>
                }
              >
                {threadName}
              </Breadcrumbs.ItemWithMenu>
            ) : isSharedThread ? (
              <Breadcrumbs.Item href={getThreadUrl()}>{threadName}</Breadcrumbs.Item>
            ) : null}
          </Breadcrumbs>
        )}
      </div>
      <div className={styles.rightControls}>
        {showShareButton && (
          <div className={styles.hideOnMobile}>
            <Button
              ref={shareButtonRef}
              leadingVisual={hasSharedId ? <UnlockIcon /> : <LockIcon />}
              disabled={isInactive}
              onClick={openShareDialog}
            >
              Share
            </Button>
          </div>
        )}
        <StaffToolsMenu />
        {customButtons}

        {showPreviewPaneButton && selectedThreadID && <PreviewPaneButton />}
      </div>
      {selectedThreadID && (
        <ConversationActionDialogs
          visibleDialog={conversationDialog}
          onClose={() => {
            // eslint-disable-next-line @eslint-react/dom/no-flush-sync
            flushSync(() => setConversationDialog(null))
            // Focus the element that opened the dialog, or fall back to the breadcrumb menu
            const targetRef = dialogOpenerRef || anchorRef
            targetRef.current?.focus()
            setDialogOpenerRef(null)
          }}
          threadName={threadName}
          threadId={selectedThreadID}
          selectedThreadId={selectedThreadID}
          onStartLoading={startLoading}
          onFinishLoading={stopLoading}
          returnFocusRef={dialogOpenerRef || anchorRef}
        />
      )}
    </div>
  )
}

function PreviewPaneButton() {
  const previewPaneOpen = useContentPreviewOpen()
  const {openPreviewPane} = useContentPreview()
  const buttonRef = useNavigableRef<HTMLButtonElement>()

  return (
    !previewPaneOpen && (
      <IconButton
        icon={SidebarExpandIcon}
        aria-label="Open workbench"
        onClick={() => {
          sendEvent('dotcom_chat.activate', {target: 'BROWSER_OPEN_BUTTON', mode: 'immersive'})
          openPreviewPane()
        }}
        ref={buttonRef}
      />
    )
  )
}
