import {CopilotNavigationWithContext} from '@github-ui/copilot-chat/components/navigation/CopilotNavigation'
import {useActivePlugin} from '@github-ui/copilot-chat/hooks/use-active-plugin'
import {findActiveComponent} from '@github-ui/copilot-chat/plugin/plugin-helpers'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import {useIsCopilotSpacesListPath, useRouteSpaceId} from '@github-ui/copilot-chat/utils/custom-copilots-helpers'
import {useCustomCopilotsEnabled} from '@github-ui/copilot-spaces/hooks'
import {useNavigableRef} from '@github-ui/navigable-ref'
import {Layout as PacerLayout} from '@github-ui/pacer/Layout'
import {useLocation} from '@github-ui/react-router'
import {Suspense, useCallback} from 'react'

import {useAutoPreviewReference} from '../hooks/use-auto-preview-reference'
import {useViewportBreakpoint} from '../hooks/use-viewport-breakpoint'
import {COPILOT_FAVICON} from '../utils/constants'
import {ContentPreview} from './ContentPreview/ContentPreview'
import {useContentPreview, useContentPreviewOpen, useResourcePanelOpen} from './ContentPreview/ContentPreviewContext'
import {ConversationView} from './ConversationView'
import {Header} from './Header'
import {NewConversationDownloadActions} from './NewConversationDownloadActions'
import {ResourcePanel} from './ResourcePanel/ResourcePanel'
import {SpacesHeader} from './Spaces/SpacesHeader'
import {SpacesConversation as SpacesConversationNext} from './Spaces/v3/components/SpacesConversation'
import {SpacesView} from './Spaces/v3/components/SpacesView'

export function Layout() {
  const state = useChatState()

  const textAreaRef = useNavigableRef<HTMLTextAreaElement>()

  const activePlugin = useActivePlugin()
  const location = useLocation()

  const customCopilotsEnabled = useCustomCopilotsEnabled()
  const isSpacesListPath = useIsCopilotSpacesListPath()
  const isSpaceList = customCopilotsEnabled && isSpacesListPath
  const customCopilotId = useRouteSpaceId()
  const {isNarrowViewport} = useViewportBreakpoint()

  // Auto-preview reference if URL contains reference_id
  useAutoPreviewReference()
  const contentPreviewOpen = useContentPreviewOpen()
  const resourcePanelOpen = useResourcePanelOpen()
  const {closePreviewPane, openPreviewPane, closeResourcePanel, openResourcePanel} = useContentPreview()

  const setPreviewPaneOpen = useCallback(
    (open: boolean) => {
      if (open) {
        openPreviewPane()
      } else {
        closePreviewPane()
      }
    },
    [closePreviewPane, openPreviewPane],
  )

  const setResourcePanelOpen = useCallback(
    (open: boolean) => {
      if (open) {
        openResourcePanel()
      } else {
        closeResourcePanel()
      }
    },
    [closeResourcePanel, openResourcePanel],
  )

  const activeComponent = findActiveComponent(activePlugin, location)
  if (activePlugin && activeComponent) {
    const Component = activeComponent.Component
    return (
      <>
        <span data-favicon-override={COPILOT_FAVICON} />
        <Suspense>
          <Component chatState={state} plugin={activePlugin} />
        </Suspense>
      </>
    )
  }

  // Helper function to render spaces-related content
  const renderSpacesContent = () => {
    if (isSpaceList) {
      return <SpacesView />
    }

    if (customCopilotId) {
      return (
        <SpacesConversationNext
          customCopilotId={customCopilotId}
          selectedThreadID={state.selectedThreadID}
          textAreaRef={textAreaRef}
        />
      )
    }

    return null
  }

  const spacesContent = renderSpacesContent()

  // MonoView for spaces
  if (spacesContent) {
    return (
      <PacerLayout
        data-testid="chat-layout"
        data-hpc
        faviconOverride={COPILOT_FAVICON}
        slimLineTopTabs={copilotFeatureFlags.copilotWorkbenchSlimLineTopTabs}
      >
        <PacerLayout.Header>
          <SpacesHeader />
        </PacerLayout.Header>

        <PacerLayout.Sidebar>
          <CopilotNavigationWithContext />
        </PacerLayout.Sidebar>

        <PacerLayout.ColumnLeft>{spacesContent}</PacerLayout.ColumnLeft>
      </PacerLayout>
    )
  }

  // PanelView for chat
  return (
    <PacerLayout
      data-testid="chat-layout"
      data-hpc
      faviconOverride={COPILOT_FAVICON}
      secondaryColumnState={[contentPreviewOpen, setPreviewPaneOpen]}
      resourcePanelState={[resourcePanelOpen, setResourcePanelOpen]}
      slimLineTopTabs={copilotFeatureFlags.copilotWorkbenchSlimLineTopTabs}
    >
      <PacerLayout.Sidebar>
        <CopilotNavigationWithContext />
      </PacerLayout.Sidebar>
      <PacerLayout.Header>
        <Header customButtons={!state.selectedThreadID && <NewConversationDownloadActions />} />
      </PacerLayout.Header>
      <PacerLayout.ColumnLeft>
        <ConversationView isMobile={isNarrowViewport} textAreaRef={textAreaRef} />
      </PacerLayout.ColumnLeft>
      <PacerLayout.ColumnRight className="d-flex">
        {copilotFeatureFlags.copilotResourcePanel && state.optedInToPreviewFeatures && resourcePanelOpen && (
          <ResourcePanel />
        )}
        <ContentPreview returnFocusRef={textAreaRef} />
      </PacerLayout.ColumnRight>
    </PacerLayout>
  )
}
