/** Per-category pagination state */
interface CategorizedPaginationState {
  starred: boolean
  userOwned: boolean
  orgOwned: boolean
  sharedWithUser: boolean
}

/** Per-category fetch more functions */
interface CategorizedFetchMore {
  starred: () => void
  userOwned: () => void
  orgOwned: () => void
  sharedWithUser: () => void
}

interface SpacesListProps {
  /** Categorized spaces for independent tab loading */
  categorizedSpaces?: CategorizedCopilotSpaces
  /** Per-tab loading states for independent loading */
  categorizedLoading?: CategorizedSpacesLoadingState
  /** Filtered categorized spaces from search endpoint */
  filteredCategorizedSpaces?: CategorizedCopilotSpaces
  /** Per-tab loading states for filtered search */
  filteredCategorizedLoading?: CategorizedSpacesLoadingState
  /** Pre-computed counts from /copilot/spaces/count API */
  spacesCounts?: CopilotSpacesCounts
  /** Loading state for spaces counts */
  isCountsLoading: boolean
  onDelete: (space: CopilotSpaceId) => Promise<void>
  onSpaceClick: () => void
  searchQuery: string
  currentUserLogin: string
  /** Per-category loading more state */
  categorizedFetchingMore?: CategorizedPaginationState
  /** Per-category has more pages state */
  categorizedHasMore?: CategorizedPaginationState
  /** Per-category fetch more functions */
  categorizedFetchMore?: CategorizedFetchMore
  /** Whether individual access is enabled for custom copilots */
  isIndividualAccessEnabled: boolean
}

