function CounterSkeleton() {
  return <SkeletonBox width="1.75em" height="1.4em" className={styles.counter} />
}

function SpacesList({
  categorizedSpaces,
  categorizedLoading,
  filteredCategorizedSpaces,
  filteredCategorizedLoading,
  spacesCounts,
  isCountsLoading,
  onDelete,
  onSpaceClick,
  searchQuery,
  currentUserLogin,
  categorizedFetchingMore,
  categorizedHasMore,
  categorizedFetchMore,
  isIndividualAccessEnabled,
}: SpacesListProps) {
  // Always use filtered spaces when searching with the search endpoint (if available)
  // Otherwise fall back to categorizedSpaces for client-side filtering
  // Check if filteredCategorizedSpaces has any defined arrays (not all undefined)
  const hasFilteredData =
    filteredCategorizedSpaces && Object.values(filteredCategorizedSpaces ?? {}).some(arr => arr !== undefined)
  const spacesToDisplay = searchQuery && hasFilteredData ? filteredCategorizedSpaces : categorizedSpaces
  const loadingStateToDisplay = searchQuery && hasFilteredData ? filteredCategorizedLoading : categorizedLoading

  const spacesSelectedTab = copilotLocalStorage.getSpacesSelectedTab()

  // Determine initial tab - if individual access is disabled and saved tab is personal/shared, default to starred
  const getInitialTab = (): CopilotSpaceTab => {
    if (!isIndividualAccessEnabled && (spacesSelectedTab === 'personal' || spacesSelectedTab === 'shared')) {
      return 'starred'
    }
    return spacesSelectedTab
  }

  const [activeTab, setActiveTab] = useState<CopilotSpaceTab>(getInitialTab)

  const handleChangeTab = useCallback((tab: CopilotSpaceTab) => {
    setActiveTab(tab)
    copilotLocalStorage.setSpacesSelectedTab(tab)
  }, [])

  const hasStarred = categorizedSpaces && categorizedSpaces.starred && categorizedSpaces.starred.length > 0
  useEffect(() => {
    if (hasStarred) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      handleChangeTab('starred')
    }
  }, [handleChangeTab, hasStarred])

  // Determine loading state for the active tab
  const isActiveTabLoading = useMemo(() => {
    if (!loadingStateToDisplay) return true

    switch (activeTab) {
      case 'starred':
        return loadingStateToDisplay.starred
      case 'personal':
        return loadingStateToDisplay.userOwned
      case 'org':
        return loadingStateToDisplay.orgOwned
      case 'shared':
        return loadingStateToDisplay.sharedWithUser
      default:
        return true
    }
  }, [loadingStateToDisplay, activeTab])

  // Get the spaces for the active tab directly from categorized spaces if available
  const activeTabSpaces = useMemo(() => {
    switch (activeTab) {
      case 'starred':
        return spacesToDisplay?.starred ?? []
      case 'personal':
        return spacesToDisplay?.userOwned ?? []
      case 'org':
        return spacesToDisplay?.orgOwned ?? []
      case 'shared':
        return spacesToDisplay?.sharedWithUser ?? []
      default:
        return []
    }
  }, [spacesToDisplay, activeTab])

  // Apply search filtering to the active tab spaces
  // If we're using server-side search (hasFilteredData is true), return as-is
  // Otherwise fall back to client-side filtering
  const filteredSpaces = useMemo(() => {
    // If no search query or server-side filtering is active, return all spaces
    if (hasFilteredData || !searchQuery.trim()) return activeTabSpaces

    // Client-side filtering when server-side filtered data is not available
    return activeTabSpaces.filter(space => matchesCommonSearch(space, searchQuery))
  }, [activeTabSpaces, searchQuery, hasFilteredData])

  // Calculate tab counts - use spacesCounts from API if available, otherwise fall back to calculating from arrays
  const {personalSpacesCount, orgSpacesCount, starredSpacesCount, sharedSpacesCount} = useMemo(() => {
    // If we have counts from the API and no search query, use them directly
    if (spacesCounts && !searchQuery.trim()) {
      return {
        personalSpacesCount: spacesCounts.user_owned_spaces,
        orgSpacesCount: spacesCounts.org_owned_spaces,
        starredSpacesCount: spacesCounts.starred_spaces,
        sharedSpacesCount: spacesCounts.shared_with_me_spaces,
      }
    }

    // If there's a search query, we need to count from the data
    if (spacesToDisplay) {
      const applySearchFilter = (arr: IndexCopilotSpace[] | undefined) => {
        if (!arr) return 0
        // If no search query, return full count
        if (!searchQuery.trim()) return arr.length
        // If using server-side filtered data, arrays are already filtered
        if (hasFilteredData) return arr.length
        // Otherwise, filter client-side for counting
        return arr.filter(space => matchesCommonSearch(space, searchQuery)).length
      }

      return {
        personalSpacesCount: applySearchFilter(spacesToDisplay.userOwned),
        orgSpacesCount: applySearchFilter(spacesToDisplay.orgOwned),
        starredSpacesCount: applySearchFilter(spacesToDisplay.starred),
        sharedSpacesCount: applySearchFilter(spacesToDisplay.sharedWithUser),
      }
    }

    // If the above failed then return zeros
    return {personalSpacesCount: 0, orgSpacesCount: 0, starredSpacesCount: 0, sharedSpacesCount: 0}
  }, [spacesCounts, spacesToDisplay, searchQuery, hasFilteredData])

  // Helper to count total unfiltered spaces
  const getTotalSpacesCount = useCallback((): number => {
    if (!categorizedSpaces) return 0

    return (
      (categorizedSpaces.starred?.length ?? 0) +
      (categorizedSpaces.userOwned?.length ?? 0) +
      (categorizedSpaces.orgOwned?.length ?? 0) +
      (categorizedSpaces.sharedWithUser?.length ?? 0)
    )
  }, [categorizedSpaces])

  // Helper to get all spaces for creator check
  const getAllSpaces = useCallback((): IndexCopilotSpace[] => {
    if (!categorizedSpaces) return []

    return [
      ...(categorizedSpaces.starred ?? []),
      ...(categorizedSpaces.userOwned ?? []),
      ...(categorizedSpaces.orgOwned ?? []),
      ...(categorizedSpaces.sharedWithUser ?? []),
    ]
  }, [categorizedSpaces])

  const hasAnySpaces = getTotalSpacesCount() > 0

  const hasNotCreatedASpace = useMemo(() => {
    const allSpaces = getAllSpaces()
    return allSpaces.length > 0 && !allSpaces.some(space => space.creator === currentUserLogin) && !isActiveTabLoading
  }, [getAllSpaces, currentUserLogin, isActiveTabLoading])

  const hasNoMatchingSpaces = hasAnySpaces && filteredSpaces?.length === 0 && !isActiveTabLoading

  // Determine if the active tab is currently fetching more (loading next page)
  const isActiveTabFetchingMore = useMemo(() => {
    if (!categorizedFetchingMore) return false

    switch (activeTab) {
      case 'starred':
        return categorizedFetchingMore.starred
      case 'personal':
        return categorizedFetchingMore.userOwned
      case 'org':
        return categorizedFetchingMore.orgOwned
      case 'shared':
        return categorizedFetchingMore.sharedWithUser
      default:
        return false
    }
  }, [categorizedFetchingMore, activeTab])

  // Determine if the active tab has more pages to load
  const activeTabHasMore = useMemo(() => {
    // Disable pagination when searching
    if (searchQuery.trim()) return false
    if (!categorizedHasMore) return false

    switch (activeTab) {
      case 'starred':
        return categorizedHasMore.starred
      case 'personal':
        return categorizedHasMore.userOwned
      case 'org':
        return categorizedHasMore.orgOwned
      case 'shared':
        return categorizedHasMore.sharedWithUser
      default:
        return false
    }
  }, [categorizedHasMore, activeTab, searchQuery])

  // Get the fetch more function for the active tab
  const handleLoadMore = useCallback(() => {
    if (!categorizedFetchMore) return

    sendEvent('copilot_spaces.load_more_clicked', {})

    switch (activeTab) {
      case 'starred':
        categorizedFetchMore.starred()
        break
      case 'personal':
        categorizedFetchMore.userOwned()
        break
      case 'org':
        categorizedFetchMore.orgOwned()
        break
      case 'shared':
        categorizedFetchMore.sharedWithUser()
        break
    }
  }, [categorizedFetchMore, activeTab])

  // Announce search results to screen readers
  useEffect(() => {
    // Don't announce while loading or if there's no search query
    if (isActiveTabLoading || !searchQuery.trim()) return

    const count = filteredSpaces.length
    const message = count === 0 ? 'No spaces found.' : `${count} ${count === 1 ? 'space' : 'spaces'} found.`
    announce(message)
  }, [filteredSpaces.length, searchQuery, isActiveTabLoading])

  // Track the previous count to focus on first new item after load more
  const previousCountRef = useRef<number>(0)
  const wasLoadingMoreRef = useRef<boolean>(false)

  // Track when we start loading more
  useEffect(() => {
    if (isActiveTabFetchingMore) {
      previousCountRef.current = filteredSpaces.length
      wasLoadingMoreRef.current = true
    }
  }, [isActiveTabFetchingMore, filteredSpaces.length])

  // Focus on first new item after loading completes
  useEffect(() => {
    if (!isActiveTabFetchingMore && wasLoadingMoreRef.current) {
      wasLoadingMoreRef.current = false
      const previousCount = previousCountRef.current
      if (filteredSpaces.length > previousCount) {
        // Find the first new item and focus it
        const spacesList = document.getElementById('spaces-list')
        if (spacesList) {
          const listItems = spacesList.querySelectorAll('a[href]')
          const firstNewItem = listItems[previousCount] as HTMLElement | undefined
          if (firstNewItem) {
            firstNewItem.focus()
            announce(`Loaded ${filteredSpaces.length - previousCount} more spaces`)
          }
        }
      }
    }
  }, [isActiveTabFetchingMore, filteredSpaces.length])

  return (
    <ListBlock>
      <ListBlock.Header>
        {/* This really needs a loading state*/}
        <div role="tablist" aria-label="Filter spaces" className={styles.filterButtons}>
          <button
            onClick={() => handleChangeTab('starred')}
            role="tab"
            aria-selected={activeTab === 'starred'}
            aria-controls="spaces-list"
            id="starred-tab"
            className={styles.button}
          >
            Starred{' '}
            {isCountsLoading && !searchQuery ? (
              <CounterSkeleton />
            ) : (
              <span className={styles.counter}>{starredSpacesCount}</span>
            )}
          </button>
          {isIndividualAccessEnabled && (
            <button
              onClick={() => handleChangeTab('personal')}
              role="tab"
              aria-selected={activeTab === 'personal'}
              aria-controls="spaces-list"
              id="personal-tab"
              className={styles.button}
            >
              Yours{' '}
              {isCountsLoading && !searchQuery ? (
                <CounterSkeleton />
              ) : (
                <span className={styles.counter}>{personalSpacesCount}</span>
              )}
            </button>
          )}
          {isIndividualAccessEnabled && (
            <button
              onClick={() => handleChangeTab('shared')}
              role="tab"
              aria-selected={activeTab === 'shared'}
              aria-controls="spaces-list"
              id="shared-with-me-tab"
              className={clsx(styles.button, styles.sharedSpacesTab)}
            >
              Shared with me{' '}
              {isCountsLoading && !searchQuery ? (
                <CounterSkeleton />
              ) : (
                <span className={styles.counter}>{sharedSpacesCount}</span>
              )}
            </button>
          )}
          <button
            onClick={() => handleChangeTab('org')}
            role="tab"
            aria-selected={activeTab === 'org'}
            aria-controls="spaces-list"
            id="org-tab"
            className={styles.button}
          >
            Organizations{' '}
            {isCountsLoading && !searchQuery ? (
              <CounterSkeleton />
            ) : (
              <span className={styles.counter}>{orgSpacesCount}</span>
            )}
          </button>
        </div>
      </ListBlock.Header>
      <ListBlock.List loading={isActiveTabLoading} id="spaces-list" aria-labelledby={activeTab}>
        {!hasAnySpaces && !isActiveTabLoading ? (
          <FirstSpaceEmptyState />
        ) : hasNotCreatedASpace && activeTab === 'personal' ? (
          <FirstSpaceEmptyState />
        ) : hasNoMatchingSpaces ? (
          <ListBlock.EmptyState>
            <p>
              {activeTab === 'starred' && 'Spaces you star will appear here.'}
              {activeTab === 'personal' && 'Spaces you create will appear here.'}
              {activeTab === 'org' && 'Spaces belonging to your organizations will appear here.'}
              {activeTab === 'shared' && 'Shared spaces will appear here.'}
            </p>
            <CreateSpaceButton />
            <DocsLink />
          </ListBlock.EmptyState>
        ) : (
          <>
            {filteredSpaces?.map(copilotSpace => (
              <SpacesListItem
                key={copilotSpace.owner ? `${copilotSpace.owner}/${copilotSpace.id}` : copilotSpace.id}
                copilotSpace={copilotSpace}
                onDelete={() => onDelete(copilotSpace)}
                onClick={onSpaceClick}
              />
            ))}
            {activeTabHasMore && (
              <li className={styles.loadMoreContainer}>
                <Button
                  variant="invisible"
                  onClick={handleLoadMore}
                  disabled={isActiveTabFetchingMore}
                  className={styles.loadMoreButton}
                  aria-label={isActiveTabFetchingMore ? 'Loading more spaces' : 'Load more spaces'}
                >
                  {isActiveTabFetchingMore ? (
                    <span className={styles.loadMoreContent}>
                      <Spinner size="small" />
                      Loading...
                    </span>
                  ) : (
                    'Load more'
                  )}
                </Button>
              </li>
            )}
          </>
        )}
      </ListBlock.List>
    </ListBlock>
  )
}

export function SpacesView() {
  const state = useChatState()
  const dispatch = useChatDispatch()
  const {showCopilotSpacesMcpBanner} = state
  const {transactionalMessageBanner} = useAppPayload<CopilotImmersivePayload>()
  const isIndividualAccessEnabled = state.customCopilotsIndividualAccessEnabled

  const paginationEnabled = copilotFeatureFlags.copilotSpacesPagination

  // Use paginated or non-paginated hook based on feature flag
  const paginatedResult = useFetchPaginatedCategorizedSpaces(paginationEnabled, {
    individualAccessEnabled: isIndividualAccessEnabled,
  })
  const nonPaginatedResult = useFetchCategorizedSpaces(!paginationEnabled, {
    individualAccessEnabled: isIndividualAccessEnabled,
  })

  // Select the appropriate result based on feature flag
  const categorizedSpaces = paginationEnabled ? paginatedResult.categorizedSpaces : nonPaginatedResult.categorizedSpaces
  const categorizedLoading = paginationEnabled
    ? paginatedResult.categorizedLoading
    : nonPaginatedResult.categorizedLoading
  const categorizedFetchingMore = paginationEnabled ? paginatedResult.categorizedFetchingMore : undefined
  const categorizedHasMore = paginationEnabled ? paginatedResult.categorizedHasMore : undefined
  const categorizedFetchMore = paginationEnabled ? paginatedResult.categorizedFetchMore : undefined

  const [deletionError, setDeletionError] = useState<Error | null>(null)
  const [searchQuery, setSearchQuery] = useState('')

  // Always enable filtered search when there's a search query
  const isFilteredSearchEnabled = searchQuery.trim() !== ''

  const {filteredCategorizedSpaces, filteredCategorizedLoading} = useFetchFilteredCategorizedSpaces(
    isFilteredSearchEnabled,
    searchQuery,
    {individualAccessEnabled: isIndividualAccessEnabled},
  )

  // Fetch spaces counts from the API when feature flag is enabled
  const {data: spacesCounts, isLoading: isCountsLoading} = useFetchSpacesCount(true)

  const {mutateAsync: deleteCustomCopilot} = useDeleteCopilotSpace()

  const handleCopilotSpaceDelete = async (item: CopilotSpaceId) => {
    try {
      await deleteCustomCopilot(item)
      setDeletionError(null)
    } catch (err) {
      setDeletionError(err instanceof Error ? err : new Error(String(err)))
    }
  }

  const handleOnClickCopilotSpace = () => {
    sendEvent('dotcom_chat.activate', {
      target: 'SPACES_VIEW_SPACE_SELECTED',
      mode: 'immersive',
    })
  }

  const handleSpacesMcpBannerDismissal = async () => {
    // Update state immediately
    dispatch({type: 'DISMISS_COPILOT_SPACES_MCP_BANNER'})

    // Persist dismissal to server
    await verifiedFetch(dismissUserNoticePath({noticeName: 'copilot_spaces_install_mcp_banner'}), {
      method: 'POST',
    })
  }

  return (
    <ErrorBoundary fallback={<ErrorFallback regionName="Spaces" />}>
      {deletionError && (
        <Flash variant="danger">
          <AlertIcon />
          There was a problem deleting your space.
        </Flash>
      )}
      <ContentView.Container width="small">
        {isFeatureEnabled('ipm_global_transactional_message_spaces') && transactionalMessageBanner ? (
          <ContentView.Banner>
            <TransactionalMessageBanner banner={transactionalMessageBanner} />
          </ContentView.Banner>
        ) : null}
        {showCopilotSpacesMcpBanner ? (
          <ContentView.Banner>
            <Banner
              title="Try Spaces in VSCode"
              hideTitle
              icon={<McpIcon />}
              description="Spaces are available in VSCode! Get started using Spaces with the GitHub MCP server."
              variant="upsell"
              primaryAction={
                <Banner.PrimaryAction as="a" href={MCP_LINK} target="_blank" rel="noopener noreferrer">
                  Install
                </Banner.PrimaryAction>
              }
              onDismiss={() => {
                void handleSpacesMcpBannerDismissal()
              }}
            />
          </ContentView.Banner>
        ) : null}
        <ContentView.Header>
          <ContentView.Title>{title}</ContentView.Title>
          <ContentView.Description>{description}</ContentView.Description>
          <ContentView.Actions>
            <CreateSpaceButton primary />
          </ContentView.Actions>
        </ContentView.Header>

        <SearchInput onSearch={setSearchQuery} aria-label="Search spaces" />

        <ContentView.Section>
          <SpacesList
            categorizedSpaces={categorizedSpaces}
            categorizedLoading={categorizedLoading}
            filteredCategorizedSpaces={filteredCategorizedSpaces}
            filteredCategorizedLoading={filteredCategorizedLoading}
            spacesCounts={spacesCounts}
            isCountsLoading={isCountsLoading}
            onDelete={handleCopilotSpaceDelete}
            onSpaceClick={handleOnClickCopilotSpace}
            searchQuery={searchQuery}
            currentUserLogin={state.currentUserLogin}
            categorizedFetchingMore={categorizedFetchingMore}
            categorizedHasMore={categorizedHasMore}
            categorizedFetchMore={categorizedFetchMore}
            isIndividualAccessEnabled={isIndividualAccessEnabled}
          />
        </ContentView.Section>
      </ContentView.Container>
    </ErrorBoundary>
  )
}
