// eslint-disable-next-line primer-react/enforce-css-module-default-import
import './copilot-immersive-v1.module.css'

import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import type {NavigatorRouteRegistration} from '@github-ui/react-core/app-routing-types'
import {TransitionType} from '@github-ui/react-core/app-routing-types'
import {jsonRoute} from '@github-ui/react-core/json-route'
import {registerNavigatorApp} from '@github-ui/react-core/register-app'

import {App} from './App'
import {ChatView} from './routes/ChatView'
import {CopilotImmersive} from './routes/CopilotImmersive'
import {CopilotImmersiveLayout} from './routes/CopilotImmersiveLayout'
import {SpacesConversationView} from './routes/SpacesConversationView'
import {SpacesLayout} from './routes/SpacesLayout'
import {SpacesListView} from './routes/SpacesListView'

/**
 * Nested layout routes (behind copilot_immersive_layout_routes flag).
 *
 * Route tree:
 *   /copilot (CopilotImmersiveLayout — Relay, providers, hooks)
 *     └── (ChatView — pathless layout, renders chat UI)
 *         ├── /copilot (index)
 *         ├── /copilot/c/:threadID
 *         ├── /copilot/r/:owner/:repository
 *         ├── /copilot/share/:threadID
 *         ├── /copilot/loops
 *         ├── /copilot/l/:loopID
 *         ├── /copilot/workbench
 *         ├── /copilot/spark
 *         ├── /copilot/agents
 *         ├── /copilot/tasks/pull/:globalID
 *         └── /copilot/t/:owner/:repository/:taskID
 *     └── (SpacesLayout — pathless layout, PacerLayout shell)
 *         ├── /copilot/spaces (SpacesListView)
 *         └── (SpacesConversationView — pathless layout, renders conversation)
 *             ├── /copilot/spaces/:spaceID
 *             ├── /copilot/spaces/:owner/:spaceNumber
 *             ├── /copilot/spaces/:owner/:spaceNumber/edit
 *             ├── /copilot/spaces/:spaceID/edit
 *             └── /copilot/spaces/new
 *
 * ChatView and SpacesConversationView are pathless layout routes that render
 * the full view UI. Their children are Component-less entries that exist only
 * for path matching.
 *
 * Plugin routes (loops, workbench, spark, agents, tasks) are nested under
 * ChatView intentionally: CopilotImmersiveLayout intercepts them via the
 * plugin system before <Outlet /> renders, so ChatView never mounts for those
 * paths. But if a plugin fails to match, ChatView renders as fallback — this
 * matches main's behavior where Layout always falls back to the chat UI.
 * Eventually, plugins may become proper route Components rendered via
 * <Outlet />, at which point they can be lifted out of the ChatView subtree.
 *
 * When the flag is off, all routes use the monolithic CopilotImmersive component
 * (identical to main's behavior).
 */

function layoutRoutes(): NavigatorRouteRegistration[] {
  return [
    jsonRoute({
      path: '/copilot',
      Component: CopilotImmersiveLayout,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
      children: [
        // Chat — ChatView is a pathless layout, children are path matchers
        {
          Component: ChatView,
          children: [
            {index: true},
            {path: '/copilot/c/:threadID'},
            {path: '/copilot/r/:owner/:repository'},
            {path: '/copilot/share/:threadID'},
            {path: '/copilot/loops'},
            {path: '/copilot/l/:loopID'},
            {path: '/copilot/workbench'},
            {path: '/copilot/spark'},
            // TODO: rename to /tasks once we have migrated /agents to /tasks
            {path: '/copilot/agents'},
            {path: '/copilot/tasks/pull/:globalID'},
            {path: '/copilot/t/:owner/:repository/:taskID'},
          ],
        },
        // Spaces — SpacesLayout provides PacerLayout shell
        {
          Component: SpacesLayout,
          children: [
            {path: '/copilot/spaces', Component: SpacesListView},
            // SpacesConversationView is a pathless layout, children are path matchers
            {
              Component: SpacesConversationView,
              children: [
                {path: '/copilot/spaces/:spaceID'},
                {path: '/copilot/spaces/:owner/:spaceNumber'},
                {path: '/copilot/spaces/:owner/:spaceNumber/edit'},
                {path: '/copilot/spaces/:spaceID/edit'},
                {path: '/copilot/spaces/new'},
              ],
            },
          ],
        },
      ],
    }),
  ]
}

function flatRoutes(): NavigatorRouteRegistration[] {
  return [
    jsonRoute({path: '/copilot', Component: CopilotImmersive, transitionType: TransitionType.TRANSITION_WITHOUT_FETCH}),
    jsonRoute({
      path: '/copilot/c/:threadID',
      Component: CopilotImmersive,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
    }),
    jsonRoute({path: '/copilot/r/:owner/:repository', Component: CopilotImmersive}),
    jsonRoute({path: '/copilot/share/:threadID', Component: CopilotImmersive}),
    jsonRoute({
      path: '/copilot/loops',
      Component: CopilotImmersive,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
    }),
    jsonRoute({
      path: '/copilot/l/:loopID',
      Component: CopilotImmersive,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
    }),
    jsonRoute({
      path: '/copilot/workbench',
      Component: CopilotImmersive,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
    }),
    jsonRoute({
      path: '/copilot/spark',
      Component: CopilotImmersive,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
    }),
    jsonRoute({path: '/copilot/spaces', Component: CopilotImmersive}),
    jsonRoute({path: '/copilot/spaces/:spaceID', Component: CopilotImmersive}),
    jsonRoute({path: '/copilot/spaces/:owner/:spaceNumber', Component: CopilotImmersive}),
    jsonRoute({path: '/copilot/spaces/:owner/:spaceNumber/edit', Component: CopilotImmersive}),
    jsonRoute({path: '/copilot/spaces/:spaceID/edit', Component: CopilotImmersive}),
    jsonRoute({path: '/copilot/spaces/new', Component: CopilotImmersive}),
    // TODO: rename to /tasks once we have migrated /agents to /tasks
    jsonRoute({path: '/copilot/agents', Component: CopilotImmersive}),
    jsonRoute({
      path: '/copilot/tasks/pull/:globalID',
      Component: CopilotImmersive,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
    }),
    jsonRoute({
      path: '/copilot/t/:owner/:repository/:taskID',
      Component: CopilotImmersive,
      transitionType: TransitionType.TRANSITION_WITHOUT_FETCH,
    }),
  ]
}

registerNavigatorApp('copilot-immersive-v1', () => ({
  App,
  routes: copilotFeatureFlags.immersiveLayoutRoutes ? layoutRoutes() : flatRoutes(),
}))
