import {useAutoLoadTrace} from '@github-ui/copilot-chat/components/tracing/utilities/use-auto-load-trace'
import {useActivePlugin} from '@github-ui/copilot-chat/hooks/use-active-plugin'
import {findActiveComponent} from '@github-ui/copilot-chat/plugin/plugin-helpers'
// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/utils/CopilotChatContext'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {Outlet, useLocation} from '@github-ui/react-router'
import {RelayEnvironmentProvider, relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'
import {Suspense} from 'react'

import {CopilotImmersiveProviders} from '../components/CopilotImmersiveProviders'
import {ImmersiveDisabled} from '../components/ImmersiveDisabled'
import {useRoutedThreads} from '../hooks/use-routed-threads'
import {COPILOT_FAVICON} from '../utils/constants'
import type {CopilotImmersivePayload} from './payloads'

const environment = relayEnvironmentWithMissingFieldHandlerForNode()

/**
 * Layout route component for the copilot-immersive app.
 *
 * This component is used as the `Component` for the parent `/copilot` route. It provides
 * shared providers (Relay, CopilotImmersiveProviders) and hooks (useRoutedThreads,
 * useAutoLoadTrace) that are stable across child route transitions, then renders
 * <Outlet /> to display the matched child route (ChatView, SpacesListView, etc.).
 */
export function CopilotImmersiveLayout() {
  return (
    <RelayEnvironmentProvider environment={environment}>
      <ImmersiveLayoutInner />
    </RelayEnvironmentProvider>
  )
}

function ImmersiveLayoutInner() {
  const payload = useAppPayload<CopilotImmersivePayload>()

  if (!payload?.copilotChatSettingEnabled) {
    return <ImmersiveDisabled />
  }

  return (
    <CopilotImmersiveProviders payload={payload}>
      <ImmersiveLayoutContent />
    </CopilotImmersiveProviders>
  )
}

function ImmersiveLayoutContent() {
  useRoutedThreads()
  useAutoLoadTrace()

  const state = useChatState()
  const activePlugin = useActivePlugin()
  const location = useLocation()
  const activeComponent = findActiveComponent(activePlugin, location)

  if (activePlugin && activeComponent) {
    const Component = activeComponent.Component
    return (
      <>
        <span data-favicon-override={COPILOT_FAVICON} />
        <Suspense>
          <Component chatState={state} plugin={activePlugin} />
        </Suspense>
      </>
    )
  }

  return <Outlet />
}
