import {useAutoLoadTrace} from '@github-ui/copilot-chat/components/tracing/utilities/use-auto-load-trace'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {RelayEnvironmentProvider, relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'

import {CopilotImmersiveProviders} from '../components/CopilotImmersiveProviders'
import {ImmersiveDisabled} from '../components/ImmersiveDisabled'
import {Layout} from '../components/Layout'
import {useRoutedThreads} from '../hooks/use-routed-threads'
import type {CopilotImmersivePayload} from './payloads'

const environment = relayEnvironmentWithMissingFieldHandlerForNode()

export function CopilotImmersive() {
  return (
    <RelayEnvironmentProvider environment={environment}>
      <CopilotImmersiveNoRelay />
    </RelayEnvironmentProvider>
  )
}

// This component is used to render the immersive experience without the relay environment
// This is useful for testing purposes when the relay environment is provided by renderRelay test helper
export function CopilotImmersiveNoRelay() {
  const payload = useAppPayload<CopilotImmersivePayload>()
  const copilotSetting = payload?.copilotChatSettingEnabled

  if (copilotSetting) {
    return (
      <CopilotImmersiveProviders payload={payload}>
        <Immersive />
      </CopilotImmersiveProviders>
    )
  } else {
    return <ImmersiveDisabled />
  }
}

function Immersive() {
  useRoutedThreads()
  // ensure that we load any saved traces for the current thread
  useAutoLoadTrace()

  return <Layout />
}
